// HTML: <img data-src="photo.jpg" src="placeholder.jpg">

let observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      let img = entry.target;
      img.src = img.dataset.src;  // load real image
      observer.unobserve(img);    // stop watching
    }
  });
}, { rootMargin: "200px" });  // start loading 200px before visible

document.querySelectorAll("img[data-src]").forEach(img => {
  observer.observe(img);
});

let box = document.querySelector(".resizable-box");
let display = document.querySelector(".size-display");

let observer = new ResizeObserver(entries => {
  for (let entry of entries) {
    let { width, height } = entry.contentRect;
    display.textContent = `${Math.round(width)}x${Math.round(height)}`;
  }
});

observer.observe(box);
// Updates automatically when the box is resized!

// Measure LCP
let lcpObserver = new PerformanceObserver((entry) => {
  let lastEntry = entry.getEntries().pop();
  console.log("LCP:", lastEntry.startTime, "ms");
});
lcpObserver.observe({ type: "largest-contentful-paint", buffered: true });

// Measure CLS
let clsValue = 0;
let clsObserver = new PerformanceObserver((entry) => {
  for (let shift of entry.getEntries()) {
    if (!shift.hadRecentInput) {
      clsValue += shift.value;
    }
  }
  console.log("CLS:", clsValue);
});
clsObserver.observe({ type: "layout-shift", buffered: true });

requestIdleCallback((deadline) => {
  while (deadline.timeRemaining() > 0 && taskQueue.length > 0) {
    processTask(taskQueue.shift());
  }
  if (taskQueue.length > 0) {
    requestIdleCallback(arguments.callee);  // continue later
  }
});

// Practical: prefetch pages during idle time
function prefetchPages(urls) {
  let index = 0;
  function doWork(deadline) {
    while (deadline.timeRemaining() > 0 && index < urls.length) {
      let link = document.createElement("link");
      link.rel = "prefetch";
      link.href = urls[index++];
      document.head.appendChild(link);
    }
    if (index < urls.length) {
      requestIdleCallback(doWork);
    }
  }
  requestIdleCallback(doWork);
}
